import { chromium } from 'playwright';
export async function boot(){
const b=await chromium.launch({args:['--use-angle=swiftshader','--ignore-gpu-blocklist']}); const p=await b.newPage({viewport:{width:390,height:844}});
const errs=[]; p.on('console',m=>{if(m.type()==='error'||(m.type()==='warning'&&!/GL Driver/.test(m.text())))errs.push(m.type()+': '+m.text().slice(0,300))}); p.on('pageerror',e=>errs.push('pageerror '+e.message));
await p.goto('http://127.0.0.1:8099/'); await p.waitForTimeout(7000);
await p.evaluate(()=>{const cc=window.cc;setInterval(()=>{const fix=n=>{n.layer=33554432;n.children.forEach(fix)};fix(cc.director.getScene().getChildByName('Canvas'))},100)});
await p.waitForTimeout(500);
return {b,p,errs};}
export async function dump(p){return p.evaluate(()=>{const cc=window.cc;const out=[];const cam=cc.director.getScene().getComponentInChildren(cc.Camera);
const w=n=>{if(!n.activeInHierarchy)return;const l=n.getComponent(cc.Label);const bt=n.getComponent(cc.Button);if(l||bt){const wp=n.worldPosition;const sp=new cc.Vec3();cam.worldToScreen(wp,sp);const v=cc.view;const r=cc.screen.devicePixelRatio||1;
out.push({name:n.name,text:l?l.string:(n.getComponentInChildren(cc.Label)?.string||''),btn:!!bt,x:sp.x/r,y:844-sp.y/r})}n.children.forEach(w)};w(cc.director.getScene().getChildByName('Canvas'));return out;})}
export async function clickText(p,t){const d=await dump(p);const e=d.find(e=>e.btn&&e.text.includes(t));if(!e)throw new Error('no btn '+t+' :: '+d.filter(x=>x.btn).map(x=>x.text).join('|'));await p.mouse.click(e.x,e.y);await p.waitForTimeout(1200);return e;}

