test('每地点盒子数3~6及签的增减', () => {
  const g = newGame();
  g.day = 1;

  g.phase = 'fortune';
  g.fortune = { tier: 'good' } as any;
  g.fortuneLocation = null;
  g.acceptFortune();
  for (const loc of LOCATIONS) {
    const count = g.boxesAt(loc.id).length;
    assert.ok(count >= 4 && count <= 8, `${loc.id} count ${count}`);
  }

  g.phase = 'fortune';
  g.fortune = { tier: 'meh' } as any;
  g.acceptFortune();
  for (const loc of LOCATIONS) {
    const count = g.boxesAt(loc.id).length;
    assert.ok(count >= 3 && count <= 6, `${loc.id} count ${count}`);
  }

  g.phase = 'fortune';
  g.fortune = { tier: 'bad' } as any;
  g.acceptFortune();
  for (const loc of LOCATIONS) {
    const count = g.boxesAt(loc.id).length;
    assert.ok(count >= 2 && count <= 5, `${loc.id} count ${count}`);
  }
});

