import { chromium } from 'playwright';
const b = await chromium.launch({args:['--use-angle=swiftshader','--ignore-gpu-blocklist']});
const p = await b.newPage({viewport:{width:390,height:844}});
await p.goto('http://127.0.0.1:8099/'); await p.waitForTimeout(6000);
const info = await p.evaluate(()=>{
  const cc = window.cc;
  const scene = cc.director.getScene();
  const cam = scene.getComponentInChildren(cc.Camera);
  const canvas = scene.getChildByName('Canvas');
  const pick = n => n ? {name:n.name, layer:n.layer} : null;
  const screen = canvas?.getChildByName('screen');
  const hud = canvas?.getChildByName('HUD');
  return {
    enums: {DEFAULT: cc.Layers.Enum.DEFAULT, UI_2D: cc.Layers.Enum.UI_2D, UI_3D: cc.Layers.Enum.UI_3D},
    camera: {name: cam.node.name, layer: cam.node.layer, visibility: cam.visibility, _visibility: cam._visibility},
    canvas: pick(canvas), canvasChildren: canvas?.children.map(pick),
    hudChildren: hud?.children.map(pick),
    screenChildren: screen?.children.map(pick),
    sampleDeep: (()=>{const out=[];(function w(n){if(n.getComponent(cc.Label)||n.getComponent(cc.Graphics))out.push({name:n.name,layer:n.layer});n.children.forEach(w)})(canvas);return out.slice(0,15)})()
  };
});
console.log(JSON.stringify(info,null,1));
await p.screenshot({path:'shots/before.png'});
await p.evaluate(()=>{const cc=window.cc;setInterval(()=>{const fix=n=>{n.layer=33554432;n.children.forEach(fix)};fix(cc.director.getScene().getChildByName('Canvas'))},100)});
await p.waitForTimeout(600);
await p.screenshot({path:'shots/after.png'});
await b.close();
EOF
