import { chromium } from 'playwright';
const b = await chromium.launch({args:['--use-angle=swiftshader','--ignore-gpu-blocklist']});
const p = await b.newPage({viewport:{width:390,height:844}});
const errs=[]; p.on('console',m=>{if(m.type()==='error')errs.push(m.text().slice(0,200))}); p.on('pageerror',e=>errs.push('pageerror '+e.message));
await p.goto('http://127.0.0.1:8099/'); await p.waitForTimeout(8000);
const dump=()=>p.evaluate(()=>{const cc=window.cc;const c=cc.director.getScene().getChildByName('Canvas');const out=[];(function w(n){const l=n.getComponent(cc.Label);if(l)out.push({t:l.string,btn:!!n.getComponent(cc.Button)});n.children.forEach(w)})(c);return out;});
// 点击"就它了"
const find=async(t)=>p.evaluate(t=>{const cc=window.cc;const c=cc.director.getScene().getChildByName('Canvas');let r=null;(function w(n){const l=n.getComponent(cc.Label);if(l&&l.string.includes(t)&&n.getComponent(cc.Button)){const wp=n.worldPosition;const sp=new cc.Vec3();const cam=cc.director.getScene().getComponentInChildren(cc.Camera);cam.worldToScreen(wp,sp);const d=cc.screen.devicePixelRatio||1;r={x:sp.x/d,y:844-sp.y/d}}n.children.forEach(w)})(c);return r;},t);
const btn=await find('就它了'); console.log('btn',JSON.stringify(btn)); if(btn)await p.mouse.click(btn.x,btn.y);
await p.waitForTimeout(1500);
const d1=await dump(); console.log('MAP', JSON.stringify(d1.map(x=>x.t).filter(Boolean)));
await p.screenshot({path:'shots/map.png'});
const loc=await find('华强北'); if(loc)await p.mouse.click(loc.x,loc.y); await p.waitForTimeout(1500);
const d2=await dump(); console.log('LOC', JSON.stringify(d2.map(x=>x.t).filter(Boolean)));
await p.screenshot({path:'shots/loc.png'});
console.log('ERRS',JSON.stringify(errs));
await b.close();
EOF
