 const items=s.children.map(n=>{const l=n.getComponent(cc.Label)||n.getComponentInChildren(cc.Label);return {name:n.name,text:l?l.string.replace(/\n/g,'|'):null,x:+n.position.x.toFixed(2),y:+n.position.y.toFixed(2)}});
 const btns=items.filter(i=>i.text&&i.text.includes('体力'));
