import { chromium } from 'playwright';
const b=await chromium.launch({args:['--use-angle=swiftshader','--ignore-gpu-blocklist']});
const p=await b.newPage({viewport:{width:390,height:844}});
await p.addInitScript(()=>{ window.wx={ getWindowInfo:()=>({windowHeight:844,windowWidth:390}), getMenuButtonBoundingClientRect:()=>({top:52,bottom:88,left:290,right:377,width:87,height:36}), getSystemInfoSync:()=>({windowHeight:844,windowWidth:390}) }; });
const errs=[]; p.on('pageerror',e=>errs.push(e.message));
await p.goto('http://127.0.0.1:8099/'); await p.waitForTimeout(8000);
const top=await p.evaluate(()=>{const cc=window.cc;const c=cc.director.getScene().getChildByName('Canvas');const hud=c.getChildByName('HUD');
 const get=n=>{const l=n.getComponent(cc.Label);return l?{t:l.string,y:+n.position.y.toFixed(1)}:null};
 const strip=hud.children.find(n=>n.name==='hud_strip');
 return {day:get(hud.getChildByName('day')),time:get(hud.getChildByName('time')),money:get(hud.getChildByName('money')),strip:strip?{y:+strip.position.y.toFixed(1)}:null};
});
console.log('capsule-topbar',JSON.stringify(top),'errs',JSON.stringify(errs));
const find=async t=>p.evaluate(t=>{const cc=window.cc;const c=cc.director.getScene().getChildByName('Canvas');const cam=cc.director.getScene().getComponentInChildren(cc.Camera);let r=null;(function w(n){if(n.getComponent(cc.Button)){const s=n.getComponentInChildren(cc.Label)?.string||'';if(s.includes(t)){const sp=new cc.Vec3();cam.worldToScreen(n.worldPosition,sp);const d=cc.screen.devicePixelRatio||1;r={x:sp.x/d,y:844-sp.y/d}}}n.children.forEach(w)})(c);return r;},t);
let btn=await find('就它了'); await p.mouse.click(btn.x,btn.y); await p.waitForTimeout(1200);
btn=await find('华强北'); await p.mouse.click(btn.x,btn.y); await p.waitForTimeout(1500);
const hint=await p.evaluate(()=>{const cc=window.cc;const c=cc.director.getScene().getChildByName('Canvas');
 let res=null;(function w(n){const l=n.getComponent(cc.Label);if(l&&l.string.includes('拖动')){res={text:l.string,color:[l.color.r,l.color.g,l.color.b,l.color.a],comps:n.components.map(x=>x.__classname__||x.name||(x.constructor&&x.constructor.name))};}n.children.forEach(w)})(c);return res;});
console.log('hint',JSON.stringify(hint),'errs',JSON.stringify(errs));
await b.close();
" 2>&1 | tail -20", "description": "Runtime test capsule offset and hint styling", "timeoutMs": 300000}

