private refresh(): void {
  if (!this.screenRoot) return;
  this.screenRoot.destroyAllChildren();

  if (this.locationView && this.game.phase !== 'location') {
    this.locationView.hide();
    this.locationView = null;
  }

  this.updateHUD();

  switch (this.game.phase) {
    case 'fortune':
      this.showFortune();
      break;
    case 'map':
      this.showMap();
      break;
    case 'location':
      this.showLocation();
      break;
    case 'home':
      this.showHome();
      break;
    case 'collapsed':
      this.showCollapsed();
      break;
    case 'lost':
      this.showLost();
      break;
    case 'won':
      this.showWon();
      break;
    default:
      break;
  }
}

