import { Game } from '../src/core/game';
import { CONFIG, EVENTS, ITEMS } from '../src/core/config';

class MockRng {
  nextQueue: number[] = [];
  chanceQueue: boolean[] = [];
  intQueue: number[] = [];
  pickQueue: any[] = [];
  seenChance: number[] = [];
  next() { return this.nextQueue.length ? this.nextQueue.shift()! : 0.5; }
  int(a: number, b: number) { return this.intQueue.length ? this.intQueue.shift()! : a; }
  pick<T>(arr: T[]) { return this.pickQueue.length ? this.pickQueue.shift()! : arr[0]; }
  chance(p: number) { this.seenChance.push(p); return this.chanceQueue.length ? this.chanceQueue.shift()! : false; }
}

const fails: string[] = [];
function ok(name: string, cond: boolean, detail = '') {
  console.log(`${cond ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + detail : ''}`);
  if (!cond) fails.push(name);
}
function newGame(seed = 7) {
  const g = new Game(seed); g.startGame();
  g.day = 5; g.stamina = 50; g.hunger = 40; g.mood = 50; g.money = 0;
  g.phase = 'event'; g.location = 'baishizhou';
  g.bannedToday = [];
  (g as any).boxes = new Map([['baishizhou', []]]);
  const r = new MockRng(); (g as any).rng = r;
  return { g, r };
}
function ev(g: Game, id: string, options: string[] = ['a']) {
  g.phase = 'event'; g.pendingEvent = { id, name: id, options } as any;
}

console.log('EVENTS count =', EVENTS.length, EVENTS.map(e => e.id).join(','));

// 1 wallet
{
  const { g } = newGame(); ev(g, 'wallet'); g.resolveEvent(0);
  ok('wallet +¥20', g.money === 20, `money=${g.money}`);
  ok('wallet mood +20', g.mood === 70, `mood=${g.mood}`);
  ok('wallet phase location', g.phase === 'location', g.phase);
}
