{
  const { g } = newGame(); ev(g, 'auntie'); g.resolveEvent(0);
  ok('auntie hunger +30', g.hunger === 70, `hunger=${g.hunger}`);
  ok('auntie mood +15', g.mood === 65, `mood=${g.mood}`);
}
// 3 delivery
{
  const { g } = newGame(); ev(g, 'delivery'); g.resolveEvent(0);
  ok('delivery hunger +25', g.hunger === 65, `hunger=${g.hunger}`);
}
// 4 cat
{
  const { g } = newGame();
  g.floor = [{ uid: 1, itemId: 'cold_bun' }] as any;
  ev(g, 'cat', ['喂它', '不喂']); g.resolveEvent(0);
  ok('cat feed catLuck=3', g.catLuck === 3, `catLuck=${g.catLuck}`);
  ok('cat feed eats food', g.floor.length === 0, `floor=${g.floor.length}`);
  const boxes = [0,1,2,3].map(i => ({ id: `box_${i}`, size: 'small' as const, opened: false }));
  g.hunger = 90; g.stamina = 100;
  (g as any).boxes.set('baishizhou', boxes);
  const seq: number[] = [];
  for (let i = 0; i < 3; i++) { g.dig(`box_${i}`, 0); seq.push(g.catLuck); }
  ok('catLuck after 3 digs=0', g.catLuck === 0, `seq=${seq.join(',')}`);
}
// 4b cat not feed
{
  const { g } = newGame(); g.floor = [{ uid: 1, itemId: 'cold_bun' }] as any;
  ev(g, 'cat', ['喂它', '不喂']); g.resolveEvent(1);
  ok('cat not feed keeps luck', g.catLuck === 0 && g.floor.length === 1, `luck=${g.catLuck} floor=${g.floor.length}`);
}
// 5 rain
{
  const { g, r } = newGame(); r.chanceQueue = [false];
  ev(g, 'rain'); g.resolveEvent(0);
  ok('rain set', g.raining === true, `raining=${g.raining}`);
  g.stamina = 100; g.goHome();
  ok('rain persists after home', g.raining === true, `raining=${g.raining} phase=${g.phase}`);
  g.lastDayReport = null;
  g.sleep();
  ok('rain cleared next day', g.raining === false && g.day === 6, `raining=${g.raining} day=${g.day}`);
}
// 6 rival
{
  const { g } = newGame(); const b = (g as any).boxes;
  ev(g, 'rival', ['让给他', '比谁掏得快']); g.resolveEvent(1, true);
  const boxes = b.get('baishizhou');
  ok('rival win adds big box', boxes.length === 1 && boxes[0].size === 'big', `n=${boxes.length} size=${boxes[0]?.size}`);
}
{
  const { g } = newGame(); ev(g, 'rival'); g.resolveEvent(1, false);
  ok('rival lose -10 stamina', g.stamina === 40, `stamina=${g.stamina}`);
}
{
  const { g } = newGame(); ev(g, 'rival'); g.resolveEvent(0);
  ok('rival yield mood -5', g.mood === 45, `mood=${g.mood}`);
}
// 7 patrol
{
  const { g } = newGame(); ev(g, 'patrol'); g.resolveEvent(0);
  ok('patrol leave -5 stamina', g.stamina === 45, `stamina=${g.stamina}`);
  ok('patrol leave bans location', g.bannedToday.includes('baishizhou'), JSON.stringify(g.bannedToday));
  ok('patrol leave -> map', g.phase === 'map', g.phase);
}
{
  const { g, r } = newGame(); r.chanceQueue = [true];
  ev(g, 'patrol'); g.resolveEvent(1);
  ok('patrol bluff win stays location', g.phase === 'location' && g.bannedToday.length === 0, `${g.phase} banned=${JSON.stringify(g.bannedToday)}`);
}
{
  const { g, r } = newGame(); r.chanceQueue = [false];
  ev(g, 'patrol'); g.resolveEvent(1);
  ok('patrol bluff fail mood -8 & ban', g.mood === 42 && g.bannedToday.includes('baishizhou') && g.phase === 'map', `mood=${g.mood} banned=${JSON.stringify(g.bannedToday)}`);
}
// 8 guard
{
  const { g } = newGame(); ev(g, 'guard'); g.resolveEvent(0);
  ok('guard bans & -> map', g.bannedToday.includes('baishizhou') && g.phase === 'map', `${g.phase} ${JSON.stringify(g.bannedToday)}`);
}
// 9 night warmth
{
  const mk = (warm: boolean) => {
    const { g, r } = newGame(11);
    g.phase = 'home'; g.hunger = 50; g.mood = 50; g.day = 5;
    g.lastDayReport = { day: 5, income: 0, soldItems: [], hungerLeft: 50, quip: '' } as any;
    r.chanceQueue = [warm];
    g.sleep();
    return { g, r };
  };
  const a = mk(true), b = mk(false);
  ok('warmth flag set', a.g.lastDayReport?.warmth === true && b.g.lastDayReport?.warmth !== true, `a=${a.g.lastDayReport?.warmth} b=${b.g.lastDayReport?.warmth}`);
  ok('warmth hunger +15', a.g.hunger - b.g.hunger === 15, `a=${a.g.hunger} b=${b.g.hunger}`);
  ok('warmth chance arg=0.2', a.r.seenChance[0] === 0.2 && b.r.seenChance[0] === 0.2, JSON.stringify(a.r.seenChance));
  ok('warmth not an EventDef', !EVENTS.some(e => (e.id as string) === 'night_warmth' || (e.id as string) === 'warmth'), EVENTS.map(e => e.id).join(','));
}
console.log('---');
console.log('FAILS:', fails.length ? fails.join(' | ') : 'none');
process.exit(fails.length ? 1 : 0);
