{"command": "mkdir -p /tmp/ly6 && cat > /tmp/ly6/verify.ts <<'EOF'
import { Game } from '/workspace/lingyuan15/src/core/game';
import { CONFIG, EVENTS, ITEMS } from '/workspace/lingyuan15/src/core/config';

class MockRng {
  nextQueue: number[] = []; chanceQueue: boolean[] = []; intQueue: number[] = []; pickQueue: any[] = []; seenChance: number[] = [];
  next() { return this.nextQueue.length ? this.nextQueue.shift()! : 0.5; }
  int(a: number, b: number) { return this.intQueue.length ? this.intQueue.shift()! : a; }
  pick<T>(arr: T[]) { return this.pickQueue.length ? this.pickQueue.shift()! : arr[0]; }
  chance(p: number) { this.seenChance.push(p); return this.chanceQueue.length ? this.chanceQueue.shift()! : false; }
}
const fails: string[] = [];
const ok = (n: string, c: boolean, d = '') => { console.log(`${c ? 'PASS' : 'FAIL'} ${n}${d ? ' :: ' + d : ''}`); if (!c) fails.push(n); };
function newGame(seed = 9) {
  const g = new Game(seed); g.startGame();
  g.day = 5; g.stamina = 50; g.hunger = 40; g.mood = 50; g.money = 0;
  g.phase = 'event'; g.location = 'baishizhou'; g.bannedToday = [];
  (g as any).boxes = new Map([['baishizhou', []]]);
  const r = new MockRng(); (g as any).rng = r;
  return { g, r };
}
const ev = (g: Game, id: string, options: string[] = ['a']) => { g.phase = 'event'; g.pendingEvent = { id, name: id, options } as any; };

console.log('EVENTS:', EVENTS.map(e => e.id).join(','), 'count=', EVENTS.length);
{ const { g } = newGame(); ev(g, 'wallet'); g.resolveEvent(0);
  ok('钱包 +¥20/心情+20', g.money === 20 && g.mood === 70 && g.phase === 'location', `money=${g.money} mood=${g.mood}`); }
{ const { g } = newGame(); ev(g, 'auntie'); g.resolveEvent(0);
  ok('阿姨 +30 饱腹 +15 心情', g.hunger === 70 && g.mood === 65, `${g.hunger}/${g.mood}`); }
{ const { g } = newGame(); ev(g, 'delivery'); g.resolveEvent(0);
  ok('外卖 +25 饱腹', g.hunger === 65, `${g.hunger}`); }
{ const { g } = newGame(); g.bag = [{ uid: 1, itemId: 'cold_bun', x: 0, y: 0, w: 1, h: 1 }];
  ev(g, 'cat', ['喂它', '不喂']); g.resolveEvent(0);
  ok('喂猫只扣背包食物、不加饱腹', g.bag.length === 0 && g.hunger === 40 && g.catLuck === 3, `bag=${g.bag.length} hunger=${g.hunger} luck=${g.catLuck}`);
  const boxes = [0,1,2,3].map(i => ({ id: `b${i}`, size: 'small' as const, opened: false }));
  g.hunger = 90; g.stamina = 100; (g as any).boxes.set('baishizhou', boxes);
  const seq: number[] = []; for (let i = 0; i < 3; i++) { g.dig(`b${i}`, 0); seq.push(g.catLuck); }
  ok('catLuck 3 次掏盒归零', g.catLuck === 0, `seq=${seq.join(',')}`); }
{ const { g } = newGame(); g.bag = []; g.floor = [{ uid: 7, itemId: 'cold_bun' }] as any;
  ev(g, 'cat', ['喂它', '不喂']); g.resolveEvent(0);
  ok('无背包食物提示且不动地面食物', g.catLuck === 0 && g.floor.length === 1 && g.hunger === 40 && g.lastEventNotice.includes('没吃的'), `notice=${g.lastEventNotice}`); }
{ const { g } = newGame(); g.bag = [{ uid: 1, itemId: 'cold_bun', x: 0, y: 0, w: 1, h: 1 }];
  ev(g, 'cat'); g.resolveEvent(1);
  ok('猫不喂不消耗', g.catLuck === 0 && g.bag.length === 1, `${g.catLuck}/${g.bag.length}`); }
{ const { g, r } = newGame(); r.chanceQueue = [false]; ev(g, 'rain'); g.resolveEvent(0);
  const during = g.raining; g.stamina = 100; g.goHome(); const afterHome = g.raining;
  g.lastDayReport = null; g.sleep();
  ok('雨当天持续、次日清除', during && afterHome && !g.raining && g.day === 6, `${during}/${afterHome}->${g.raining} day=${g.day}`); }
{ const { g } = newGame(); const b = (g as any).boxes; ev(g, 'rival', ['让给他', '比谁掏得快']); g.resolveEvent(1, true);
  const boxes = b.get('baishizhou');
  ok('抢地盘赢 + 大盒', boxes.length === 1 && boxes[0].size === 'big', `n=${boxes.length} size=${boxes[0]?.size}`); }
{ const { g } = newGame(); ev(g, 'rival'); g.resolveEvent(1, false);
  ok('抢地盘输 -10 体力', g.stamina === 40 && g.phase === 'location', `${g.stamina} ${g.phase}`); }
{ const { g } = newGame(); ev(g, 'rival'); g.resolveEvent(0);
  ok('抢地盘让 -5 心情', g.mood === 45, `${g.mood}`); }
{ const { g } = newGame(); ev(g, 'patrol'); g.resolveEvent(0);
  ok('巡逻离开 -5 封点回地图', g.stamina === 45 && g.bannedToday.includes('baishizhou') && g.phase === 'map', `${g.stamina} ${JSON.stringify(g.bannedToday)} ${g.phase}`); }
{ const { g, r } = newGame(); r.chanceQueue = [true]; ev(g, 'patrol'); g.resolveEvent(1);
  ok('巡逻装散步赢留地点', g.phase === 'location' && g.bannedToday.length === 0, `${g.phase}`); }
{ const { g, r } = newGame(); r.chanceQueue = [false]; ev(g, 'patrol'); g.resolveEvent(1);
  ok('巡逻装散步输 -8 封点', g.mood === 42 && g.bannedToday.includes('baishizhou') && g.phase === 'map', `${g.mood} ${JSON.stringify(g.bannedToday)}`); }
{ const { g } = newGame(); ev(g, 'guard'); g.resolveEvent(0);
  ok('保安封点回地图', g.bannedToday.includes('baishizhou') && g.phase === 'map', `${g.phase}`); }
{
  const mk = (warm: boolean) => { const { g, r } = newGame(13); g.phase = 'home'; g.hunger = 50; g.mood = 50; g.day = 5; g.lastDayReport = null; r.chanceQueue = [warm]; g.sleep(); return { g, r }; };
  const a = mk(true), b = mk(false);
  ok('温情由 chance 决定', a.g.lastNightWarmth === true && b.g.lastNightWarmth === false, `${a.g.lastNightWarmth}/${b.g.lastNightWarmth}`);
  ok('温情 +15 饱腹', a.g.hunger - b.g.hunger === 15, `${a.g.hunger}/${b.g.hunger}`);
  ok('chance 参数=0.2', a.r.seenChance[0] === 0.2, `${a.r.seenChance}`);
  ok('warmth 标记睡后仍在', a.g.lastNightWarmth === true, `${a.g.lastNightWarmth}`);
}
{ const g = new Game(21); g.startGame(); g.day = 1;
  let min = 99, max = 0, badMin = 99, badMax = 0;
  for (const tier of ['good', 'meh', 'bad'] as const) for (let i = 0; i < 40; i++) {
    g.phase = 'fortune'; g.fortune = { tier } as any; g.fortuneLocation = null; g.acceptFortune();
    for (const loc of ['baishizhou','huaqiangbei','dongmen','futian_cbd','nanshan_tech','sz_bay','window_world','university_town']) {
      const c = g.boxesAt(loc).length; min = Math.min(min, c); max = Math.max(max, c);
      if (tier === 'bad') { badMin = Math.min(badMin, c); badMax = Math.max(badMax, c); }
    }
  }
  ok('盒子数 3~6', min >= 3 && max <= 6, `min=${min} max=${max}; bad=${badMin}~${badMax}`);
  ok('坏签 3~4', badMin >= 3 && badMax <= 4, `${badMin}~${badMax}`); }
{ const g = new Game(31); g.startGame(); g.day = 3; g.phase = 'location'; g.location = 'baishizhou'; g.hunger = 50; g.money = 0;
  g.bag = [
    { uid: 1, itemId: 'empty_water_bottle', x: 0, y: 0, w: 1, h: 1 }, { uid: 2, itemId: 'old_newspaper', x: 1, y: 0, w: 1, h: 1 },
    { uid: 3, itemId: 'crushed_can', x: 2, y: 0, w: 1, h: 1 }, { uid: 4, itemId: 'left_slipper', x: 0, y: 1, w: 1, h: 1 }];
  const r = new MockRng(); r.nextQueue = [0.1, 0.9, 0.7, 0.5]; r.chanceQueue = [false, false]; (g as any).rng = r;
  g.collapse();
  const afterCollapse = g.bag.length;
  const keptValue = g.bag.reduce((s, p) => s + (ITEMS.find(i => i.id === p.itemId)?.price ?? 0), 0);
  g.wakeUp();
  const afterWake = g.bag.length, moneyAfterWake = g.money;
  g.acceptFortune(); (g as any).boxes = new Map([['baishizhou', []]]); g.travel('baishizhou'); g.goHome();
  ok('倒下丢一半、保留并结算', afterCollapse === 2 && afterWake === 2 && moneyAfterWake === 0 && g.bag.length === 0 && g.money === keptValue, `collapse=${afterCollapse} wake=${afterWake} money=${moneyAfterWake}->${g.money} kept=${keptValue}`); }
{ const g = new Game(41); g.startGame(); g.phase = 'home'; g.money = 20; g.hunger = 10;
  ok('饭 ¥20', g.buyFood() && g.money === 0 && g.hunger === 30, `${g.money}/${g.hunger}`); }
{ const g = new Game(51); g.startGame(); g.day = 15; g.phase = 'home'; g.hunger = 100;
  const r = new MockRng(); r.chanceQueue = [false]; (g as any).rng = r; g.sleep();
  ok('第 15 天存活判胜', g.phase === 'won', g.phase); }
{ const g = new Game(61); g.startGame(); g.phase = 'location'; g.location = 'baishizhou'; g.hunger = 1; g.stamina = 100;
  (g as any).boxes = new Map([['baishizhou', [{ id: 'b', size: 'small', opened: false }]]]);
  const r = new MockRng(); r.chanceQueue = [false]; (g as any).rng = r; g.dig('b', 0);
  ok('饱腹 0 判失败', g.phase === 'lost', g.phase); }
{ const g = new Game(71); g.startGame(); g.phase = 'location'; g.location = 'baishizhou'; g.stamina = 50;
  g.bag = [{ uid: 1, itemId: 'old_newspaper', x: 0, y: 0, w: 1, h: 1 }, { uid: 2, itemId: 'old_phone', x: 1, y: 0, w: 1, h: 1 }];
  g.goHome(); const rep = g.lastDayReport!;
  ok('最离谱与吐槽同物品', rep.bestItem === '旧手机' && rep.quip.includes('旧手机'), `${rep.bestItem}`);
  ok('金额不换行空格', rep.quip.includes('¥\u00A0') && !rep.quip.includes('¥ '), JSON.stringify(rep.quip)); }
console.log('---'); console.log('FAILS:', fails.length ? fails.join(' | ') : 'none');
process.exit(fails.length ? 1 : 0);
EOF
