import { chromium } from 'playwright';
const b=await chromium.launch({args:['--use-angle=swiftshader','--ignore-gpu-blocklist']});
const p=await b.newPage({viewport:{width:390,height:844}});
const errs=[]; p.on('pageerror',e=>errs.push(e.message));
await p.goto('http://127.0.0.1:8099/'); await p.waitForTimeout(8000);
const open=async(id,name,opts)=>p.evaluate(({id,name,opts})=>{const cc=window.cc;const c=cc.director.getScene().getChildByName('Canvas');const comp=c.getComponents(cc.Component).find(x=>x.game);comp.game.phase='event';comp.game.location='baishizhou';comp.game.pendingEvent={id,name,options:opts};comp.refresh();},{id,name,opts});
const clickLabel=async t=>{const pos=await p.evaluate(t=>{const cc=window.cc;const c=cc.director.getScene().getChildByName('Canvas');const cam=cc.director.getScene().getComponentInChildren(cc.Camera);let r=null;(function w(n){const l=n.getComponent(cc.Label);if(l&&l.string===t){const sp=new cc.Vec3();cam.worldToScreen(n.worldPosition,sp);const d=cc.screen.devicePixelRatio||1;r={x:sp.x/d,y:844-sp.y/d}}n.children.forEach(w)})(c);return r;},t); if(!pos)throw new Error('no label '+t); await p.mouse.click(pos.x,pos.y);};
const mask=async()=>p.evaluate(()=>{const cc=window.cc;const c=cc.director.getScene().getChildByName('Canvas');const s=c.getChildByName('screen');const dim=s.children.find(n=>n.name==='fx_dim');const ev=s.children.find(n=>n.name==='EventView');const g=dim&&dim.components.find(x=>(x.__classname__||x.name)==='cc.Graphics');return {dimIdx:s.children.indexOf(dim),evIdx:s.children.indexOf(ev),alpha:g?g.fillColor.a:null};});
// rival yield
await open('rival','抢地盘',['让给他','比谁掏得快']); await p.waitForTimeout(2200);
console.log('mask',JSON.stringify(await mask()));
await clickLabel('让给他'); await p.waitForTimeout(2500);
const rival=await p.evaluate(()=>{const cc=window.cc;const c=cc.director.getScene().getChildByName('Canvas');const s=c.getChildByName('screen');
 const labels=[];const pinks=[];(function w(n){const l=n.getComponent(cc.Label);if(l&&l.string)labels.push({t:l.string.replace(/\n/g,'|'),y:+n.position.y.toFixed(1)});const g=n.components&&n.components.find(x=>(x.__classname__||x.name)==='cc.Graphics');if(g&&g.fillColor&&g.fillColor.r===255&&g.fillColor.g===110&&g.fillColor.b===110)pinks.push(n.name);n.children.forEach(w)})(s);
 return {labels:labels.slice(-6),pinks,panel:!!s.getChildByName('result_panel')};});
console.log('rival',JSON.stringify(rival));
// cat no bag food
await open('cat','猫',['喂它','不喂']); await p.waitForTimeout(2200);
const compState=await p.evaluate(()=>{const cc=window.cc;const c=cc.director.getScene().getChildByName('Canvas');const comp=c.getComponents(cc.Component).find(x=>x.game);comp.game.bag=[];comp.game.floor=[];comp.game.catLuck=0;return true;});
await clickLabel('喂它'); await p.waitForTimeout(2500);
const cat=await p.evaluate(()=>{const cc=window.cc;const c=cc.director.getScene().getChildByName('Canvas');const comp=c.getComponents(cc.Component).find(x=>x.game);const labs=[];(function w(n){const l=n.getComponent(cc.Label);if(l&&l.string)labs.push(l.string.replace(/\n/g,'|'));(n.children||[]).forEach(w)})(c);return {notice:comp.game.lastEventNotice,catLuck:comp.game.catLuck,labels:labs.slice(-5)};});
console.log('cat',JSON.stringify(cat),'errs',JSON.stringify(errs)); await b.close();
" 2>&1 | tail -12", "description": "Runtime check rival result, cat notice, mask alpha", "timeoutMs": 300000}

